import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    score = 0
    my_c = 0
    op_c = 0
    for m, o in history:
        if m == 'C' and o == 'C':
            score += 3
        elif m == 'C' and o == 'D':
            score += 0
        elif m == 'D' and o == 'C':
            score += 5
        else:
            score += 1
        if m == 'C':
            my_c += 1
        if o == 'C':
            op_c += 1

    my_rate = my_c / n
    op_rate = op_c / n
    last = history[-1]
    last_pair = last[0] + last[1]

    if n < 8:
        return 'C'

    if last_pair == 'DD':
        if op_rate < 0.15 and my_rate > 0.5:
            return 'C'
        return 'D'

    if last_pair == 'DC':
        return 'D'

    if last_pair == 'CD':
        if op_rate < 0.3:
            return 'C'
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    if op_rate > 0.85:
        return 'C'

    if op_rate < 0.2:
        if my_rate < 0.5:
            return 'C'
        return 'D'

    if my_rate > 0.75 and op_rate > 0.55:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if op_rate > 0.5:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    if rng.random() < 0.3:
        return 'D'
    return 'C'

